#include <stdio.h>

int main(void) {
    int n;
    scanf("%d", &n);
    int arr[20000];
    for (int i = 0; i < n; i++) {
        scanf("%d", &arr[i]);
    }
    int target;
    scanf("%d", &target);

    int left = 0;
    int right = n - 1;
    int result = -1;
    while (left < right) {
        int mid = left + (right - left) / 2;
        if (arr[mid] == target) {
            result = mid;
            break;
        } else if (arr[mid] < target) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }
    printf("%d\n", result);
    return 0;
}

